Q: Error creating bean with name &#39;org.springframework.security.filterChains A: <p>Define your <code>userdetail</code> bean in <code>security.xml</code> configuration, something like this:</p>

<pre><code>&lt;?xml version="1.0" encoding="UTF-8"?&gt;
&lt;beans:beans xmlns="http://www.springframework.org/schema/security"
 xmlns:beans="http://www.springframework.org/schema/beans"
 xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
 xsi:schemaLocation="http://www.springframework.org/schema/beans
       http://www.springframework.org/schema/beans/spring-beans-3.2.xsd
       http://www.springframework.org/schema/security
       http://www.springframework.org/schema/security/spring-security-3.2.xsd"&gt;

&lt;http use-expressions="true"&gt;
&lt;intercept-url pattern="/add_role.htm" access="hasRole('ROLE_ADMIN')" /&gt;
&lt;form-login login-page="/login.htm"/&gt;
&lt;logout logout-url="/logout"/&gt;
 &lt;/http&gt;


&lt;authentication-manager&gt;
&lt;authentication-provider user-service-ref="userdetail"&gt;
    &lt;password-encoder hash="bcrypt" /&gt;
&lt;/authentication-provider&gt;
&lt;/authentication-manager&gt;

&lt;beans:bean id="userdetail" class="com.controller.UserDetail" /&gt;
&lt;/beans:beans&gt;
</code></pre>
